import{z as B,x as A,o as s,c as p,q as r,j as n,D as l,d as E,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"隔离级别","description":"","frontmatter":{"title":"隔离级别","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/isolation-levels.md","filePath":"cs/isolation-levels.md","lastUpdated":1791063341000}'),d={name:"cs/isolation-levels.md"};function D(C,a,m,S,F,h){const t=A("Mermaid");return s(),p("div",null,[a[2]||(a[2]=r('<h1 id="隔离级别" tabindex="-1">隔离级别 <a class="header-anchor" href="#隔离级别" aria-label="Permalink to &quot;隔离级别&quot;">​</a></h1><div class="epigraph"><p>SQL 用允许哪些异常来标档，而不是只用冲突图；同一档在锁引擎与 MVCC 上实现可以不同。</p><footer>—— Berenson, Bernstein, Gray, Melton, O&#39;Neil and O&#39;Neil, A Critique of ANSI SQL Isolation Levels, SIGMOD 1995</footer></div><p><a href="/cs/phantom-write-skew">上一课</a>给出快照与版本。本课不重写可见性函数。缺口是：应用需要比「可串行 / 不可」更细的旋钮。ANSI SQL 用脏读、不可重复读、幻读定义读未提交到可串行；Berenson 等人指出这套异常表既不精确也不完整，快照隔离夹在中间，写偏斜没有名字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>严格 2PL 太贵，读未提交又太脏。缺口不是新的并发算法，而是<strong>对实现与用户都可说的档位</strong>：哪些现象允许。读已提交：不读未提交脏数据。可重复读：同一行再读不改。可串行：冲突可串行（或实现声称的等价）。幻读是谓词结果集变，项锁挡不住。</p><p>Berenson 补充：丢失更新、写偏斜、读倾斜。本课把它们收成对照表，不把某一厂商的默认档神化。</p><p><span class="marginnote">术语翻译：写偏斜就是两个事务各自读到同一份快照、各自更新互不相交的行并各自提交——单独看都合法，合起来却违反业务约束，比如两位值班医生同时把「最后一班岗」标记为已接手。</span></p><p><span class="marginnote">异常是教学语言；真正的规格仍是允许的调度集合。同一「REPEATABLE READ」在 InnoDB 与另一引擎上可能一个是间隙锁，一个是快照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用现象定义允许集，再用锁或 MVCC 去实现该允许集。读已提交可用短 S 锁或每语句快照。可重复读可用事务快照或长 S 锁。可串行用严格 2PL、SSI 或真串行。本课不规定默认；只要求：选档 = 选允许的异常，代价回写到阻塞与中止率。</p>',10)),(s(),n(o,null,{default:l(()=>[i(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22%E5%BC%82%E5%B8%B8%3A%20%E8%84%8F%2F%E4%B8%8D%E5%8F%AF%E9%87%8D%E5%A4%8D%2F%E5%B9%BB%2F%E5%86%99%E5%81%8F%E6%96%9C%22%5D%20--%3E%20LVL%5B%22%E7%BA%A7%E5%88%AB%22%5D%0A%20%20LVL%20--%3E%20LOCK%5B%22%E9%94%81%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20LVL%20--%3E%20SNAP%5B%22%E5%BF%AB%E7%85%A7%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20LVL%20--%3E%20DL%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%BA%93%E5%86%85%E6%AD%BB%E9%94%81%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("档位越低，锁越短或快照越松，死锁与阻塞越少，应用必须能容忍相应现象。可串行下写偏斜应消失；SI 默认不消失。这把"),e("a",{href:"/cs/acid"},"ACID"),E("的 I 从「一个字母」变成可配置的集合。恢复的 A/D 不随级别减弱：未提交仍须 UNDO，已提交仍须 REDO。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：同一笔读操作，读已提交下 S 锁读完语句就放（毫秒级）；可重复读要持到事务提交（可能几秒）；锁窗口拉长，吞吐下降、死锁概率上升——选档也在选等待图。")],-1)),a[6]||(a[6]=e("p",null,"各级别各挡住哪种异常：",-1)),(s(),n(o,null,{default:l(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20RU%5B%22%E8%AF%BB%E6%9C%AA%E6%8F%90%E4%BA%A4%22%5D%20--%3E%7C%22%E6%8C%A1%E4%BD%8F%E8%84%8F%E8%AF%BB%22%7C%20RC%5B%22%E8%AF%BB%E5%B7%B2%E6%8F%90%E4%BA%A4%22%5D%0A%20%20RC%20--%3E%7C%22%E5%86%8D%E6%8C%A1%E4%B8%8D%E5%8F%AF%E9%87%8D%E5%A4%8D%E8%AF%BB%22%7C%20RR%5B%22%E5%8F%AF%E9%87%8D%E5%A4%8D%E8%AF%BB%22%5D%0A%20%20RR%20--%3E%7C%22%E5%86%8D%E6%8C%A1%E5%B9%BB%E8%AF%BB%22%7C%20SER%5B%22%E5%8F%AF%E4%B8%B2%E8%A1%8C%22%5D%0A%20%20SI%5B%22%E5%BF%AB%E7%85%A7%E9%9A%94%E7%A6%BB%22%5D%20--%3E%7C%22%E5%A4%B9%E5%9C%A8%E4%B8%AD%E9%97%B4%EF%BC%8C%E4%BB%8D%E5%85%81%E8%AE%B8%E5%86%99%E5%81%8F%E6%96%9C%22%7C%20SER%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要背诵厂商文档当理论。也不要把「最高隔离」与「正确业务」等同：业务不变量可能比冲突可串行更强（应用层约束）。本课不讲分布式隔离、因果一致性。</p><p>读未提交在教学上存在，实践几乎不用：它把脏数据交给应用，与<a href="/cs/aries-recovery">ARIES</a>的 UNDO 窗口叠在一起。后课默认：谈到隔离，先问允许哪些异常、用锁还是快照实现；阻塞等待会进入死锁。</p><p>选档是显式的正确性–吞吐交易。应用若不声明能容忍哪种异常，默认档只是厂商的工程选择，不是定理。</p><p><span class="marginnote">常见误区：初学者容易以为「可串行 = 慢到不能用」。真串行执行（单线程或分组串行）在内存热数据上反而可能最快——没有锁等待，也没有死锁检测的开销。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>同一档名在锁引擎与 MVCC 上实现可以不同，异常表才是跨引擎的语言。</p></li><li><p>后课死锁随锁变长而变频繁，选档也会选等待图。</p></li><li><p>MVCC 与 2PL 是实现；级别是允许异常的用户档。</p></li><li><p>ANSI 三现象不够；写偏斜是 SI 的对照缺口。</p></li><li><p>锁等待成环时如何打破，是库内死锁课。</p></li><li><p>出处：Berenson et al., SIGMOD 1995；SQL 标准；Gray and Reuter。</p></li></ul>',7))])}const c=B(d,[["render",D]]);export{f as __pageData,c as default};
